import{_ as n,o as e,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"BÁO CÁO HOÀN THÀNH TÁC VỤ: DA-E08-03","description":"","frontmatter":{},"headers":[],"relativePath":"wireframe/flows-report.md","filePath":"wireframe/flows-report.md"}'),a={name:"wireframe/flows-report.md"};function h(r,t,l,c,g,d){return e(),i("div",null,[...t[0]||(t[0]=[o('<p>&gt; ⚠️ <strong>[STALE 2026-09-15]</strong> User flow theo model nghiệp vụ CŨ (Workspace 1 tầng, không Agency/Package/Campaign, naming role cũ AccountManager). Xem <code>docs/ba/00-overview.md</code> cho model V2.</p><h1 id="bao-cao-hoan-thanh-tac-vu-da-e08-03" tabindex="-1">BÁO CÁO HOÀN THÀNH TÁC VỤ: DA-E08-03 <a class="header-anchor" href="#bao-cao-hoan-thanh-tac-vu-da-e08-03" aria-label="Permalink to &quot;BÁO CÁO HOÀN THÀNH TÁC VỤ: DA-E08-03&quot;">​</a></h1><p><strong>Tên tác vụ:</strong> Draw user flow diagrams for 3 main flows: content creation, approval, publishing<br><strong>Mức độ ưu tiên:</strong> 🟡 High (Cao)<br><strong>Mục tiêu:</strong> Xây dựng sơ đồ luồng người dùng (User Flow Diagrams) ở tầng UX (screen-to-screen) cho 3 hành trình cốt lõi của người dùng cuối trên Dashboard BrandHub. Giúp lập trình viên Frontend hiểu rõ cơ chế điều hướng, các điểm kích hoạt (triggers), và sự liên kết giữa các màn hình.</p><hr><h2 id="📌-checklist-nghiem-thu-acceptance-criteria" tabindex="-1">📌 Checklist Nghiệm thu (Acceptance Criteria) <a class="header-anchor" href="#📌-checklist-nghiem-thu-acceptance-criteria" aria-label="Permalink to &quot;📌 Checklist Nghiệm thu (Acceptance Criteria)&quot;">​</a></h2><ul><li>[x] <strong>Content Creation Flow (Luồng tạo nội dung):</strong><ul><li>Điểm bắt đầu: <code>Creator_Dashboard</code></li><li>Nhập prompt AI: <code>Creator_Editor</code> (giao diện cấu hình gợi ý AI)</li><li>Kết quả thế hệ AI: <code>Creator_Editor</code> (hiển thị hình ảnh/văn bản sinh ra từ AI)</li><li>Chỉnh sửa bản thảo: <code>Creator_Editor</code> (cho phép edit thủ công kết quả)</li><li>Hành động cuối: Lưu bản nháp (Save Draft) / Gửi phê duyệt (Submit for Review).</li></ul></li><li>[x] <strong>Approval Flow (Luồng phê duyệt nội dung):</strong><ul><li>Điểm bắt đầu: Nhận thông báo trên <code>AccountManager_Dashboard</code></li><li>Màn hình đánh giá: <code>AccountManager_ContentEditor</code> (xem chi tiết bài viết, hình ảnh)</li><li>Các hành động: Phê duyệt (Approve) / Từ chối hoặc Yêu cầu chỉnh sửa (<code>AccountManager_DenyContent</code> modal)</li><li>Phản hồi cho người sáng tạo: Cập nhật danh sách công việc trên <code>Creator_Workspaces</code></li><li>Đưa lên lịch đăng (nếu được duyệt): Tự động đặt lịch hiển thị trên <code>Creator_Calendar</code>.</li></ul></li><li>[x] <strong>Publishing Flow (Luồng xuất bản nội dung):</strong><ul><li>Quản lý lịch trình: <code>Creator_Calendar</code> (hiển thị bài đăng theo ngày giờ được lên lịch)</li><li>Điểm kích hoạt duyệt cuối: <code>BrandClient_ClientPortal</code> (phía đối tác/khách hàng duyệt)</li><li>Cơ chế duyệt/yêu cầu thay đổi: <code>BrandClient_CreateForm</code> / <code>BrandClient_Deny</code> / <code>BrandClient_YourRequest</code> / <code>BrandClient_NoRequest</code></li><li>Kết quả xuất bản: Chuyển đổi trạng thái sang <code>PUBLISHED</code> (thành công) hoặc <code>FAILED</code> (thất bại kèm tùy chọn thử lại - Retry).</li></ul></li><li>[x] <strong>Technical Alignment (Đồng bộ kỹ thuật):</strong><ul><li>Sử dụng các đường liên kết (connector arrows) mặc định của Figma để đồng bộ trực tiếp với các Frame thiết kế.</li><li>Mỗi nút của luồng tương ứng 100% với tên Frame của Wireframe tương ứng trong Figma.</li></ul></li></ul><hr><h2 id="🛠-chi-tiet-cac-luong-nghiem-thu-tren-figma" tabindex="-1">🛠 Chi Tiết Các Luồng Nghiệm Thu Trên Figma <a class="header-anchor" href="#🛠-chi-tiet-cac-luong-nghiem-thu-tren-figma" aria-label="Permalink to &quot;🛠 Chi Tiết Các Luồng Nghiệm Thu Trên Figma&quot;">​</a></h2><h3 id="_1-luong-tao-noi-dung-content-creation-flow" tabindex="-1">1. Luồng Tạo Nội Dung (Content Creation Flow) <a class="header-anchor" href="#_1-luong-tao-noi-dung-content-creation-flow" aria-label="Permalink to &quot;1. Luồng Tạo Nội Dung (Content Creation Flow)&quot;">​</a></h3><p>Sơ đồ mô tả quy trình từ lúc Creator truy cập hệ thống đến khi hoàn thành lưu bản nháp hoặc gửi duyệt:</p><ul><li><strong>Màn hình bắt đầu:</strong> <code>Creator_Dashboard</code> (Bản Desktop 1440px và Mobile 390px). <ul><li><em>Điểm kích hoạt (Trigger):</em> Click nút &quot;Create Content&quot; hoặc chọn Editor từ Sidebar.</li></ul></li><li><strong>Màn hình nhập gợi ý:</strong> <code>Creator_Editor</code> (Trạng thái trống). <ul><li><em>Hành động:</em> Người dùng nhập prompt AI vào khung cấu hình và click nút &quot;Generate Content&quot;.</li></ul></li><li><strong>Màn hình kết quả &amp; chỉnh sửa:</strong> <code>Creator_Editor</code> (Trạng thái hiển thị kết quả). <ul><li><em>Hành động:</em> AI tạo ra hình ảnh sản phẩm (ví dụ: chai nước hoa trên nền hoa đỏ) và nội dung chữ. Creator có thể tinh chỉnh trực tiếp văn bản này.</li></ul></li><li><strong>Hành động kết thúc:</strong> Creator chọn: <ul><li>Click <strong>Save Draft</strong> để lưu nháp cục bộ (Bài viết chuyển trạng thái <code>DRAFT</code>).</li><li>Click <strong>Submit for Review</strong> để gửi lên hệ thống phê duyệt (Bài viết chuyển trạng thái <code>PENDING_REVIEW</code>).</li></ul></li></ul><hr><h3 id="_2-luong-phe-duyet-approval-flow" tabindex="-1">2. Luồng Phê Duyệt (Approval Flow) <a class="header-anchor" href="#_2-luong-phe-duyet-approval-flow" aria-label="Permalink to &quot;2. Luồng Phê Duyệt (Approval Flow)&quot;">​</a></h3><p>Sơ đồ hướng dẫn Manager (AM) tiếp nhận thông tin và xử lý phê duyệt bài viết:</p><ul><li><strong>Nhận thông báo:</strong> AM xem danh sách công việc cần duyệt thông qua Notification Badge hoặc bảng thống kê trên <code>AccountManager_Dashboard</code>. <ul><li><em>Điểm kích hoạt (Trigger):</em> Click vào thông báo bài viết mới.</li></ul></li><li><strong>Đánh giá nội dung:</strong> AM được điều hướng tới màn hình <code>AccountManager_ContentEditor</code>. <ul><li>Tại đây, AM xem trực quan bài đăng của Creator và có 2 lựa chọn: <ol><li>Click <strong>Approve</strong> (Màu xanh): Chấp thuận bài đăng $\\rightarrow$ Bài viết chuyển trạng thái <code>APPROVED</code> và tự động hiển thị trên lịch <code>Creator_Calendar</code>.</li><li>Click <strong>Deny</strong> (Màu đỏ) $\\rightarrow$ Kích hoạt Modal Dialog <code>AccountManager_DenyContent</code> để nhập lý do từ chối / yêu cầu chỉnh sửa.</li></ol></li></ul></li><li><strong>Phản hồi hệ thống:</strong> Creator nhận được cập nhật trạng thái công việc tại <code>Creator_Workspaces</code>. Nếu bị từ chối, bài đăng quay lại trạng thái chỉnh sửa kèm lý do phản hồi của AM.</li></ul><hr><h3 id="_3-luong-xuat-ban-khach-hang-phe-duyet-publishing-flow" tabindex="-1">3. Luồng Xuất Bản &amp; Khách Hàng Phê Duyệt (Publishing Flow) <a class="header-anchor" href="#_3-luong-xuat-ban-khach-hang-phe-duyet-publishing-flow" aria-label="Permalink to &quot;3. Luồng Xuất Bản &amp; Khách Hàng Phê Duyệt (Publishing Flow)&quot;">​</a></h3><p>Mô tả cách thức khách hàng (Client) thực hiện duyệt cuối và quy trình xuất bản tự động:</p><ul><li><strong>Quản lý lịch trình:</strong> <code>Creator_Calendar</code> hiển thị các bài viết ở trạng thái <code>SCHEDULED</code> (đã lên lịch đăng).</li><li><strong>Khách hàng đánh giá:</strong> Khách hàng đăng nhập vào <code>BrandClient_ClientPortal</code> để duyệt các bài đăng thuộc thương hiệu của họ. <ul><li>Nếu đồng ý: Kích hoạt xuất bản theo đúng thời gian lên lịch.</li><li>Nếu không đồng ý hoặc muốn thay đổi: Click từ chối kích hoạt Modal <code>BrandClient_Deny</code> hoặc tạo form yêu cầu chỉnh sửa qua <code>BrandClient_CreateForm</code>.</li></ul></li><li><strong>Trạng thái yêu cầu:</strong> Các yêu cầu của Client được lưu vết tại <code>BrandClient_YourRequest</code> (hoặc quay về <code>BrandClient_NoRequest</code> khi đã xử lý xong).</li><li><strong>Kết quả xuất bản tự động (Publishing Trigger):</strong><ul><li>Hệ thống tự động đẩy bài lên các nền tảng mạng xã hội khi đến giờ.</li><li>Trạng thái bài viết được cập nhật thành <code>PUBLISHED</code> (Thành công) hoặc <code>FAILED</code> (Thất bại kèm nút bấm cho phép Creator nhấn thử lại - Retry).</li></ul></li></ul><hr><h2 id="📐-đanh-gia-tinh-đong-bo-figma-to-code" tabindex="-1">📐 Đánh Giá Tính Đồng Bộ Figma-to-Code <a class="header-anchor" href="#📐-đanh-gia-tinh-đong-bo-figma-to-code" aria-label="Permalink to &quot;📐 Đánh Giá Tính Đồng Bộ Figma-to-Code&quot;">​</a></h2><p>Tất cả các tên Frame dùng trong sơ đồ luồng người dùng trên Figma đã được đối chiếu và ánh xạ trực tiếp sang cấu trúc định tuyến và các trang thành phần trong dự án React/Vite:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tên Figma Frame</th><th style="text-align:left;">Trang Code Tương Ứng</th><th style="text-align:left;">File Code Link</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Creator_Dashboard</code></td><td style="text-align:left;">Dashboard Page</td><td style="text-align:left;">[DashboardPage.tsx](file:///d:/FPT/FA26/brandhub-ui-design/Uibrandhubs/src/app/pages/DashboardPage.tsx)</td></tr><tr><td style="text-align:left;"><code>Creator_Editor</code> / <code>AccountManager_ContentEditor</code></td><td style="text-align:left;">Editor Page</td><td style="text-align:left;">[EditorPage.tsx](file:///d:/FPT/FA26/brandhub-ui-design/Uibrandhubs/src/app/pages/EditorPage.tsx)</td></tr><tr><td style="text-align:left;"><code>AccountManager_Dashboard</code> / <code>Creator_Workspaces</code></td><td style="text-align:left;">Workspaces Page</td><td style="text-align:left;">[WorkspacePage.tsx](file:///d:/FPT/FA26/brandhub-ui-design/Uibrandhubs/src/app/pages/WorkspacePage.tsx)</td></tr><tr><td style="text-align:left;"><code>Creator_Calendar</code></td><td style="text-align:left;">Calendar Page</td><td style="text-align:left;">[CalendarPage.tsx](file:///d:/FPT/FA26/brandhub-ui-design/Uibrandhubs/src/app/pages/CalendarPage.tsx)</td></tr><tr><td style="text-align:left;"><code>BrandClient_ClientPortal</code></td><td style="text-align:left;">Client Portal Page</td><td style="text-align:left;">[ClientPortalPage.tsx](file:///d:/FPT/FA26/brandhub-ui-design/Uibrandhubs/src/app/pages/ClientPortalPage.tsx)</td></tr><tr><td style="text-align:left;"><code>AccountManager_DenyContent</code> / <code>BrandClient_Deny</code></td><td style="text-align:left;">Dialog Component</td><td style="text-align:left;">[dialog.tsx](file:///d:/FPT/FA26/brandhub-ui-design/Uibrandhubs/src/app/components/ui/dialog.tsx)</td></tr></tbody></table>',23)])])}const p=n(a,[["render",h]]);export{s as __pageData,p as default};
